<script setup lang="ts">
import {nextTick,ref,shallowRef,watch,onBeforeUnmount} from 'vue';
import type {Input,Output} from '../../shared/protocol/registry';
import {recycleNative} from '../services';
const props=defineProps<{input:Input<'recycle.native.preview'>;disabled?:boolean}>();
const view=shallowRef<Output<'recycle.native.preview'>>(),busy=ref(false),error=ref(''),dialog=ref<HTMLDialogElement>();
let generation=0,origin:HTMLElement|null=null;
function close(){generation++;dialog.value?.close();view.value=undefined;error.value='';busy.value=false;origin?.focus();}
async function open(event:MouseEvent){origin=event.currentTarget as HTMLElement;const current=++generation;busy.value=true;error.value='';view.value=undefined;await nextTick();dialog.value?.showModal();dialog.value?.querySelector<HTMLButtonElement>('[data-cancel]')?.focus();try{const result=await recycleNative.preview(props.input);if(current===generation)view.value=result;}catch(e){if(current===generation)error.value=String(e);}finally{if(current===generation)busy.value=false;}}
watch(()=>props.input,()=>{generation++;view.value=undefined;error.value='';busy.value=false;dialog.value?.close();},{deep:true});onBeforeUnmount(()=>generation++);
</script>
<template><span class="recycle-impact-entry"><button type="button" :disabled="disabled||busy" @click="open">永久删除范围与保护预览</button><Teleport to=".unified-shell"><dialog ref="dialog" class="recycle-impact-dialog" aria-label="原生永久删除范围预览" @cancel.prevent="close"><header><h2>永久删除范围与保护预览</h2></header><p v-if="busy" role="status">正在核对当前对象与引用…</p><p v-if="error" role="alert">{{error}}</p><template v-if="view"><p class="impact-notice">本预览只读取现有数据。永久删除尚未启用，关闭预览不会修改任何对象或文件。</p><dl class="impact-counts"><template v-for="(label,key) in {cards:'统一卡片',knowledge:'知识点',versions:'发布版本',cycles:'学习周期',events:'学习事件',drafts:'已发布卡片草稿',newDrafts:'未发布草稿',schedules:'排期记录',sessions:'复盘页面',referenceDocuments:'引用/回收记录',imageReferences:'图片身份引用'}" :key="key"><dt>{{label}}</dt><dd>{{view.counts[key]}}</dd></template></dl><details open><summary>删除对象及关联范围（{{view.objects.length}}）</summary><ul class="impact-objects"><li v-for="object in view.objects" :key="object.kind+object.id"><strong>{{object.label||'未命名'}}</strong><small>{{{card:'卡片',deck:'卡片集',knowledge:'知识点',draft:'未发布草稿'}[object.kind]}} · 修订 {{object.revision}} · {{object.id}}</small></li></ul></details><section aria-label="永久删除阻断原因"><h3>当前保护条件</h3><p v-for="reason in view.blockers" :key="reason">{{reason}}</p></section><p class="impact-fingerprint">数据代次 {{view.epoch}}<br/>范围指纹 {{view.fingerprint}}</p></template><footer><button type="button" data-cancel @click="close">关闭预览</button><button type="button" disabled>永久删除尚未启用</button></footer></dialog></Teleport></span></template>
<style scoped>.recycle-impact-entry{display:inline-block}.recycle-impact-dialog{box-sizing:border-box;width:min(720px,calc(100vw - 40px));max-height:85vh;overflow:auto;border:1px solid var(--border);border-radius:13px;padding:22px;background:var(--surface);color:var(--ink)}.recycle-impact-dialog::backdrop{background:#14291e66}.recycle-impact-dialog:not([open]){display:none}h2{font-size:18px;margin:0 0 14px}h3{font-size:13px}.impact-notice{padding:12px;border-radius:8px;background:var(--soft);font-size:12px}.impact-counts{display:grid;grid-template-columns:1fr auto 1fr auto;gap:8px 14px;font-size:12px;margin:16px 0}dd{margin:0;color:var(--primary);font-weight:700}.impact-objects{max-height:180px;overflow:auto;list-style:none;padding:0;font-size:12px}.impact-objects li{padding:8px 0;border-bottom:1px solid var(--border)}.impact-objects small{display:block;color:var(--muted);font-size:10px;overflow-wrap:anywhere}section p{font-size:12px;line-height:1.7;padding:10px;background:#fff7ed;border-radius:7px}.impact-fingerprint{color:var(--muted);font-size:10px;overflow-wrap:anywhere}footer{display:flex;justify-content:flex-end;gap:8px;position:sticky;bottom:-22px;background:var(--surface);padding:14px 0}summary{cursor:pointer;font-size:12px}@media(max-width:610px){.impact-counts{grid-template-columns:1fr auto}}</style>
